import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {stafftoolsOrganizationCustomPropertiesAppBuilder} from './config/app-builder'

import {definitionsIndexRoute} from './routes/definitions-index-route'
import {DefinitionsIndex} from './routes/DefinitionsIndex'
import {DefinitionsShow} from './routes/DefinitionsShow'
import {definitionsShowRoute} from './routes/definitions-show-route'
import {valuesIndexRoute} from './routes/values-index-route'
import {ValuesIndex} from './routes/ValuesIndex'

export const stafftoolsOrganizationCustomPropertiesApp =
  stafftoolsOrganizationCustomPropertiesAppBuilder.createDataRouterAppFromRoutes([
    definitionsIndexRoute.toRoute({Component: DefinitionsIndex}),
    definitionsShowRoute.toRoute({Component: DefinitionsShow}),
    valuesIndexRoute.toRoute({Component: ValuesIndex}),
  ])
registerDataRouterApp(stafftoolsOrganizationCustomPropertiesApp)
