import {Blankslate} from '@primer/react/experimental'
import {getDefinitionDetailsPath} from '../paths'
import {valuesIndexRoute} from './values-index-route'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {ValuesTable} from '@github-ui/stafftools-custom-properties-core/values/table'

export function ValuesIndex() {
  const {data} = useRouteQuery(valuesIndexRoute, 'mainQuery')
  const {properties, owner} = data

  const tableData = Object.entries(properties).map(([key, value]) => ({
    id: key,
    property: key,
    value,
  }))

  if (tableData.length === 0) {
    return (
      <Blankslate border>
        <Blankslate.Heading>No property values set for this organization</Blankslate.Heading>
      </Blankslate>
    )
  }

  return <ValuesTable data={tableData} source={owner || ''} getDefinitionDetailsPath={getDefinitionDetailsPath} />
}
