import {CheckIcon, XIcon} from '@primer/octicons-react'

type DefinitionBooleanFieldProps = {
  label: string
  value: boolean
}

export const DefinitionBooleanField = ({label, value}: DefinitionBooleanFieldProps) => {
  return (
    <span>
      <strong>{label}:</strong> {value ? <CheckIcon size={16} /> : <XIcon size={16} />}
    </span>
  )
}
